-				)
-				if (h1Match?.[1]) {
-					statusText = h1Match[1].trim()
+				statusText = firstLine
+
+				const lowerStatus = firstLine.toLowerCase()
+				if (lowerStatus.includes("down")) {
+					status = "down"
+				} else if (lowerStatus.includes("issues") || lowerStatus.includes("degraded")) {
+					status = "degraded"
+				} else {
+					// Try to extract the actual status message from the H1 tag
+					const h1Match = overviewText.match(
+						/<h1[^>]*class='[^']*heading-large[^']*'[^>]*>(.*?)<\/h1>/
+					)
+					if (h1Match?.[1]) {
+						statusText = h1Match[1].trim()
+					}
+				}
+
+				if (statusText) {
 					try {
